begin;
-- Full application flows and isolation checks. Every fixture rolls back.
do $$
declare c uuid; other_club uuid; admin_id uuid=gen_random_uuid(); member_id uuid=gen_random_uuid(); stranger_id uuid=gen_random_uuid(); book uuid; category uuid; question uuid; answer uuid; post uuid; commitment uuid; challenge uuid; round_id uuid; meeting uuid; nomination uuid; code text=upper('TEST-'||gen_random_uuid()); j jsonb; inv jsonb; op text; rejected boolean; member_membership uuid; admin_membership uuid; foreign_membership uuid; staff_post uuid; staff_question uuid; staff_answer uuid; staff_book uuid;
begin
 insert into public.clubs(name) values('TEST transaction') returning id into c;
 insert into public.club_revisions(club_id) values(c);
 insert into public.clubs(name) values('TEST other club') returning id into other_club;
 insert into public.club_revisions(club_id) values(other_club);
 insert into public.invitations(club_id,code_hash,expires_at,max_uses,bootstrap) values(c,encode(extensions.digest(code,'sha256'),'hex'),now()+interval '1 hour',1,true);
 insert into auth.users(id,email,raw_user_meta_data) values(admin_id,'qa-admin@example.invalid',jsonb_build_object('name','QA Admin','invite_code',code,'timezone','UTC'));
 if (select uses from public.invitations where code_hash=encode(extensions.digest(code,'sha256'),'hex'))<>1 then raise exception 'Invitation not consumed'; end if;
 rejected=false;
 begin insert into auth.users(id,email,raw_user_meta_data) values(gen_random_uuid(),'qa-reuse@example.invalid',jsonb_build_object('name','Reuse','invite_code',code,'timezone','UTC'));exception when others then rejected=true;end;
 if not rejected then raise exception 'Exhausted invitation accepted';end if;
 perform set_config('request.jwt.claim.sub',admin_id::text,true);
 perform set_config('role','authenticated',true);
 inv=public.bookcircle_mutate('admin.generateInvitation','{"maxUses":2,"expiresInDays":1}');
 j=public.validate_invitation(inv->>'code');if j->>'clubName'<>'TEST transaction' then raise exception 'Validation failed';end if;
 book=(public.bookcircle_mutate('reading.addBook','{"title":"Test book","author":"Author","totalPages":200,"category":"Growth","description":"Test","coverUrl":""}')#>>'{}')::uuid;
 category=(public.bookcircle_mutate('admin.saveCategory','{"name":"Discussion","active":true}')#>>'{}')::uuid;
 perform public.bookcircle_mutate('admin.setWeeklyPrompt','{"prompt":"What did you learn?"}');
 perform set_config('role','none',true);
 insert into auth.users(id,email,raw_user_meta_data) values(member_id,'qa-member@example.invalid',jsonb_build_object('name','QA Member','invite_code',inv->>'code','timezone','UTC'));
 insert into public.invitations(club_id,code_hash,expires_at,max_uses) values(other_club,encode(extensions.digest(code||'OTHER','sha256'),'hex'),now()+interval '1 hour',1);
 insert into auth.users(id,email,raw_user_meta_data) values(stranger_id,'qa-other@example.invalid',jsonb_build_object('name','Other','invite_code',code||'OTHER','timezone','UTC'));
 perform set_config('request.jwt.claim.sub',member_id::text,true);perform set_config('role','authenticated',true);
 perform public.bookcircle_mutate('profiles.update','{"name":"Member","timezone":"UTC","shareReadingDetails":false,"notificationsEnabled":true}');
 perform public.bookcircle_mutate('reading.setBook',jsonb_build_object('bookId',book,'status','reading'));
 foreach op in array array['want','reading','completed','paused'] loop
 perform public.bookcircle_mutate('reading.setBook',jsonb_build_object('bookId',book,'status',op));
 j=public.bookcircle_query('reading.myBooks');if j->0->'entry'->>'status'<>op then raise exception 'Shelf status did not update: %',op;end if;
 end loop;
 perform public.bookcircle_mutate('reading.setBook',jsonb_build_object('bookId',book,'status','reading'));
 perform public.bookcircle_mutate('reading.setGoals','{"pages":100,"minutes":150,"days":5}');
 perform public.bookcircle_mutate('reading.log',jsonb_build_object('bookId',book,'date',current_date,'startPage',0,'endPage',25,'minutes',30,'notes','Private note','reflection','Private reflection','commitment',jsonb_build_object('title','Apply it','targetDate',current_date+7)));
 j=public.bookcircle_query('reading.stats','{}');if (j->'totals'->>'pages')::int<>25 or (j->>'streak')::int<>1 then raise exception 'Incorrect reading stats: %',j;end if;
 j=public.bookcircle_query('reading.reflections','{}');if jsonb_typeof(j)<>'array' then raise exception 'Reflections must be an array';end if;
 post=(public.bookcircle_mutate('community.create',jsonb_build_object('title','Insight','content','A useful idea','chapter','1','bookId',book))#>>'{}')::uuid;
 perform public.bookcircle_mutate('community.react',jsonb_build_object('id',post,'type','helpful'));
 perform public.bookcircle_mutate('community.comment',jsonb_build_object('id',post,'content','Follow up'));
 j=public.bookcircle_query('community.feed','{"paginationOpts":{"numItems":10,"cursor":null}}');if (j->'page'->0->'post'->>'helpful')::int<>1 then raise exception 'Reaction count failed';end if;
 question=(public.bookcircle_mutate('forum.ask',jsonb_build_object('title','Anonymous question','content','How?','categoryId',category,'anonymous',true))#>>'{}')::uuid;
 perform public.bookcircle_mutate('forum.updateQuestion',jsonb_build_object('id',question,'title','Anonymous question edited','content','How to apply?'));
 perform public.bookcircle_mutate('forum.vote',jsonb_build_object('questionId',question));
 answer=(public.bookcircle_mutate('forum.answer',jsonb_build_object('questionId',question,'content','Practice it','anonymous',true))#>>'{}')::uuid;
 perform public.bookcircle_mutate('forum.accept',jsonb_build_object('questionId',question,'answerId',answer));
 perform public.toggle_forum_reaction('❤️',question,null);
 j=public.forum_reactions(question,null);
 if jsonb_array_length(j)<>1 or (j->0->>'count')::int<>1 or not (j->0->>'mine')::boolean then raise exception 'Question reaction failed';end if;
 if j::text like '%'||member_id::text||'%' then raise exception 'Reaction author identity exposed';end if;
 perform public.toggle_forum_reaction('❤️',question,null);
 if jsonb_array_length(public.forum_reactions(question,null))<>0 then raise exception 'Reaction toggle failed';end if;
 perform public.toggle_forum_reaction('💡',null,answer);
 if (public.forum_reactions(null,answer)->0->>'count')::int<>1 then raise exception 'Answer reaction failed';end if;
 rejected=false;begin perform public.toggle_forum_reaction('invalid',question,null);exception when others then rejected=true;end;if not rejected then raise exception 'Invalid emoji accepted';end if;
 j=public.bookcircle_query('forum.detail',jsonb_build_object('questionId',question));if j::text like '%'||member_id::text||'%' or j->'author'->>'name'<>'Anonymous member' then raise exception 'Anonymous author exposed';end if;
 perform public.bookcircle_mutate('forum.report',jsonb_build_object('questionId',question,'reason','Test report'));
 commitment=(public.bookcircle_mutate('club.saveCommitment',jsonb_build_object('title','Try habit','description','Daily','targetDate',current_date+7,'shared',true))#>>'{}')::uuid;
 perform public.bookcircle_mutate('club.setCommitmentStatus',jsonb_build_object('id',commitment,'status','completed','outcome','Worked'));
 perform public.bookcircle_mutate('club.saveWeeklyReview',jsonb_build_object('week',date_trunc('week',current_date)::date,'achieved',true,'lesson','Focus','improvement','Continue'));
 rejected=false;begin perform public.bookcircle_query('admin.members');exception when insufficient_privilege then rejected=true;end;if not rejected then raise exception 'Member admin access';end if;
 rejected=false;begin execute 'select * from public.forum_questions';exception when insufficient_privilege then rejected=true;end;if not rejected then raise exception 'Raw forum read allowed';end if;
 perform set_config('request.jwt.claim.sub',admin_id::text,true);
 perform public.bookcircle_mutate('club.pairMembers',jsonb_build_object('firstId',admin_id,'secondId',member_id));
 j=public.bookcircle_query('club.partner');if jsonb_array_length(j->'readingLogs')<>0 or jsonb_array_length(j->'commitments')<>1 then raise exception 'Partner privacy failed: %',j;end if;
 perform public.bookcircle_mutate('club.encourage','{"message":"Keep going!"}');
 challenge=(public.bookcircle_mutate('club.saveChallenge',jsonb_build_object('title','Read daily','description','Test','startDate',current_date,'endDate',current_date+7,'goalType','minutes','target',30))#>>'{}')::uuid;
 round_id=(public.bookcircle_mutate('club.saveVotingRound',jsonb_build_object('title','Next book','deadline',extract(epoch from now()+interval '1 day')*1000))#>>'{}')::uuid;
 perform public.bookcircle_mutate('club.nominate',jsonb_build_object('roundId',round_id,'bookId',book));
 j=public.bookcircle_query('club.votingRounds');nomination=(j->0->'nominations'->0->>'_id')::uuid;
 if j->0->'nominations'->0->>'votes' is not null then raise exception 'Open vote totals exposed';end if;
 meeting=(public.bookcircle_mutate('club.saveMeeting',jsonb_build_object('title','Monthly meeting','startsAt',extract(epoch from now()+interval '1 day')*1000,'endsAt',extract(epoch from now()+interval '1 day 1 hour')*1000,'location','Online','description','Discuss','bookId',book))#>>'{}')::uuid;
 perform public.bookcircle_mutate('forum.moderate',jsonb_build_object('questionId',question,'pinned',true,'locked',false));
 perform set_config('request.jwt.claim.sub',member_id::text,true);
 perform public.bookcircle_mutate('club.joinChallenge',jsonb_build_object('id',challenge));
 j=public.bookcircle_query('club.challenges');if not (j->0->>'completed')::boolean then raise exception 'Challenge progress failed';end if;
 perform public.bookcircle_mutate('club.vote',jsonb_build_object('nominationId',nomination));
 perform public.bookcircle_mutate('club.rsvp',jsonb_build_object('meetingId',meeting,'status','going','question','What next?'));
 perform public.bookcircle_mutate('club.reviewBook',jsonb_build_object('meetingId',meeting,'lessons',jsonb_build_array('one','two','three'),'applied','Habit','changed','Focus','improvement','More'));
 perform public.bookcircle_query('club.meetingAgenda',jsonb_build_object('meetingId',meeting));
 perform public.bookcircle_mutate('notifications.markRead');
 foreach op in array array['profiles.me','profiles.directory','reading.library','reading.myBooks','reading.logs','club.commitments','club.partner','club.meetings','community.feed','forum.list','forum.categories','notifications.list'] loop perform public.bookcircle_query(op);end loop;
 perform public.bookcircle_query('forum.answers',jsonb_build_object('questionId',question));
 perform public.bookcircle_query('community.comments',jsonb_build_object('id',post));
 perform set_config('request.jwt.claim.sub',stranger_id::text,true);
 foreign_membership=(public.bookcircle_query('profiles.me')->'membership'->>'_id')::uuid;
 rejected=false;begin perform public.toggle_forum_reaction('❤️',question,null);exception when others then rejected=true;end;if not rejected then raise exception 'Cross-club reaction allowed';end if;
 rejected=false;begin perform public.forum_reactions(null,answer);exception when others then rejected=true;end;if not rejected then raise exception 'Cross-club reaction read allowed';end if;

 rejected=false;begin perform public.bookcircle_query('forum.detail',jsonb_build_object('questionId',question));exception when others then rejected=true;end;if not rejected then raise exception 'Cross-club read';end if;
 rejected=false;begin perform public.bookcircle_mutate('community.react',jsonb_build_object('id',post,'type','helpful'));exception when others then rejected=true;end;if not rejected then raise exception 'Cross-club write';end if;
 perform set_config('request.jwt.claim.sub',admin_id::text,true);
 perform public.bookcircle_mutate('club.closeVoting',jsonb_build_object('id',round_id));
 j=public.bookcircle_query('club.votingRounds');if (j->0->'round'->>'winnerId')::uuid<>book or (j->0->'nominations'->0->>'votes')::int<>1 then raise exception 'Vote winner failed';end if;
 foreach op in array array['admin.overview','admin.members','admin.invitations','admin.reports'] loop perform public.bookcircle_query(op);end loop;
 -- Administrator role management and moderator isolation.
 admin_membership=(public.bookcircle_query('profiles.me')->'membership'->>'_id')::uuid;
 select (value->'membership'->>'_id')::uuid into member_membership from jsonb_array_elements(public.bookcircle_query('admin.members')) where value->'membership'->>'profileId'=member_id::text;
 rejected=false;begin perform public.bookcircle_mutate('admin.setMemberRole',jsonb_build_object('id',admin_membership,'role','moderator'));exception when others then rejected=sqlerrm like '%at least one active administrator%';end;if not rejected then raise exception 'Last admin demotion not blocked';end if;
 rejected=false;begin perform public.bookcircle_mutate('admin.setMemberRole',jsonb_build_object('id',foreign_membership,'role','admin'));exception when others then rejected=sqlerrm='Member not found';end;if not rejected then raise exception 'Cross-club role change allowed';end if;
 rejected=false;begin perform public.bookcircle_mutate('admin.setMemberRole',jsonb_build_object('id',member_membership,'role','superadmin'));exception when others then rejected=sqlerrm='Choose a valid role';end;if not rejected then raise exception 'Invalid role allowed';end if;
 staff_post=(public.bookcircle_mutate('community.create','{"title":"Admin insight","content":"Original","chapter":""}')#>>'{}')::uuid;
 staff_question=(public.bookcircle_mutate('forum.ask',jsonb_build_object('title','Admin question','content','Original','categoryId',category,'anonymous',true))#>>'{}')::uuid;
 staff_answer=(public.bookcircle_mutate('forum.answer',jsonb_build_object('questionId',staff_question,'content','Original answer','anonymous',true))#>>'{}')::uuid;
 perform public.bookcircle_mutate('admin.setMemberRole',jsonb_build_object('id',member_membership,'role','moderator'));
 perform set_config('request.jwt.claim.sub',member_id::text,true);
 if public.bookcircle_query('profiles.me')->'membership'->>'role'<>'moderator' then raise exception 'Promotion not visible';end if;
 -- Moderators can manage another member's shared content, including anonymous posts.
 perform public.bookcircle_mutate('community.update',jsonb_build_object('id',staff_post,'title','Moderated insight','content','Reviewed','chapter',''));
 perform public.bookcircle_mutate('forum.updateQuestion',jsonb_build_object('id',staff_question,'title','Moderated question','content','Reviewed'));
 perform public.bookcircle_mutate('forum.updateAnswer',jsonb_build_object('id',staff_answer,'content','Reviewed answer'));
 perform public.bookcircle_mutate('forum.moderate',jsonb_build_object('questionId',staff_question,'pinned',true,'locked',true));
 staff_book=(public.bookcircle_mutate('reading.addBook','{"title":"Moderator book","author":"Author","totalPages":100,"category":"Growth","description":"","coverUrl":""}')#>>'{}')::uuid;
 perform public.bookcircle_mutate('reading.editBook',jsonb_build_object('bookId',staff_book,'title','Edited book','author','Author','totalPages',120,'category','Growth','description','','coverUrl',''));
 perform public.bookcircle_mutate('reading.deleteBook',jsonb_build_object('bookId',staff_book));
 perform public.bookcircle_mutate('admin.setWeeklyPrompt','{"prompt":"Moderator prompt"}');
 perform public.bookcircle_mutate('admin.saveCategory',jsonb_build_object('id',category,'name','Moderated category','active',true));
 j=public.bookcircle_query('admin.reports');
 perform public.bookcircle_mutate('admin.resolveReport',jsonb_build_object('id',j->0->>'_id'));
 perform public.bookcircle_query('admin.overview');
 perform public.bookcircle_query('forum.moderationIdentity',jsonb_build_object('questionId',staff_question));
 -- Invitations, account status, and roles remain admin-only even via direct RPC.
 foreach op in array array['admin.members','admin.invitations'] loop
 rejected=false;begin perform public.bookcircle_query(op);exception when insufficient_privilege then rejected=true;end;if not rejected then raise exception 'Moderator read admin-only data: %',op;end if;
 end loop;
 foreach op in array array['admin.setMemberRole','admin.setMemberStatus','admin.generateInvitation','admin.revokeInvitation'] loop
 rejected=false;begin perform public.bookcircle_mutate(op,jsonb_build_object('id',member_membership,'role','admin','status','inactive','maxUses',1,'expiresInDays',1));exception when insufficient_privilege then rejected=true;end;if not rejected then raise exception 'Moderator performed admin action: %',op;end if;
 end loop;
 perform public.bookcircle_mutate('community.remove',jsonb_build_object('id',staff_post));
 perform public.bookcircle_mutate('forum.removeAnswer',jsonb_build_object('id',staff_answer));
 perform public.bookcircle_mutate('forum.removeQuestion',jsonb_build_object('id',staff_question));
 -- Demotion immediately removes content privileges for an existing session.
 perform set_config('request.jwt.claim.sub',admin_id::text,true);
 perform public.bookcircle_mutate('admin.setMemberRole',jsonb_build_object('id',member_membership,'role','member'));
 perform set_config('request.jwt.claim.sub',member_id::text,true);
 rejected=false;begin perform public.bookcircle_mutate('admin.setWeeklyPrompt','{"prompt":"Not allowed"}');exception when insufficient_privilege then rejected=true;end;if not rejected then raise exception 'Demoted member retained privileges';end if;
 rejected=false;begin perform public.bookcircle_mutate('admin.setMemberRole',jsonb_build_object('id',member_membership,'role','admin'));exception when insufficient_privilege then rejected=true;end;if not rejected then raise exception 'Member self-promotion allowed';end if;
 perform set_config('request.jwt.claim.sub',admin_id::text,true);
 -- A second admin may be promoted and demoted without removing the last admin.
 perform public.bookcircle_mutate('admin.setMemberRole',jsonb_build_object('id',member_membership,'role','admin'));
 perform public.bookcircle_mutate('admin.setMemberRole',jsonb_build_object('id',member_membership,'role','member'));

 perform set_config('role','none',true);
 update public.memberships set status='inactive' where profile_id=member_id;
 perform set_config('request.jwt.claim.sub',member_id::text,true);perform set_config('role','authenticated',true);
 rejected=false;begin perform public.bookcircle_query('reading.library');exception when insufficient_privilege then rejected=true;end;if not rejected then raise exception 'Inactive member access';end if;
 perform set_config('role','none',true);
end $$;
rollback;
select 'All transactional application and isolation checks passed' as result;
